import { readFileSync } from 'node:fs';

// Generated by scripts/build-airports.ts: { IATA: [IANA timezone, lat, lon, ICAO, city] }.
const AIRPORTS: Record<string, [string, number, number, string | null, string | null]> = JSON.parse(
  readFileSync(new URL('../data/airports.json', import.meta.url), 'utf-8')
);

export function airportTimezone(iata: string): string | null {
  return AIRPORTS[iata.toUpperCase()]?.[0] ?? null;
}

/** The ICAO code (LGW -> EGKK), which is what ATC and ADS-B tools use. */
export function airportIcao(iata: string): string | null {
  return AIRPORTS[iata.toUpperCase()]?.[3] ?? null;
}

/** The city an airport serves (LGW -> London), for people who don't know the codes by heart. */
export function airportCity(iata: string): string | null {
  return AIRPORTS[iata.toUpperCase()]?.[4] ?? null;
}

type Code = string | null | undefined;
interface ViewWithPlaces {
  legs: Array<{ origin?: Code; destination?: Code; extras?: { rotation?: { previous: Array<{ origin?: Code; destination?: Code }> } | null } | null }>;
}

/** { IATA: city } for every airport a trip view mentions, its plane's earlier flights included. */
export function placeNames(view: ViewWithPlaces | null): Record<string, string> {
  const codes = (view?.legs ?? []).flatMap((leg) => [
    leg.origin, leg.destination,
    ...(leg.extras?.rotation?.previous ?? []).flatMap((f) => [f.origin, f.destination]),
  ]);
  return Object.fromEntries(
    codes.filter((c): c is string => Boolean(c))
      .flatMap((c) => { const city = airportCity(c); return city ? [[c, city]] : []; }));
}

const EARTH_RADIUS_KM = 6371;
const rad = (deg: number) => (deg * Math.PI) / 180;

/** Great-circle distance in km, or null when either airport is unknown. */
export function distanceKm(from: string, to: string): number | null {
  const a = AIRPORTS[from.toUpperCase()];
  const b = AIRPORTS[to.toUpperCase()];
  if (!a || !b) return null;
  const [, lat1, lon1] = a;
  const [, lat2, lon2] = b;
  const h = Math.sin(rad(lat2 - lat1) / 2) ** 2 + Math.cos(rad(lat1)) * Math.cos(rad(lat2)) * Math.sin(rad(lon2 - lon1) / 2) ** 2;
  return 2 * EARTH_RADIUS_KM * Math.asin(Math.sqrt(h));
}

/**
 * Rough gate-to-gate time: cruise at ~800 km/h plus 40 minutes of taxi, climb and descent.
 * Good to about an hour, which is enough to tell which day a scheduled arrival departed on.
 */
export function estimatedBlockMinutes(from: string, to: string): number | null {
  const km = distanceKm(from, to);
  return km === null ? null : Math.round((km / 800) * 60 + 40);
}
